CREATE TYPE "TaskType" AS ENUM ('CONTENT_CREATION','SOCIAL_MEDIA','GRAPHIC_DESIGN','VIDEO_EDITING','COPYWRITING','SEO','PAID_ADVERTISING','EMAIL_MARKETING','WEB_DEVELOPMENT','RESEARCH','CLIENT_COMMUNICATION','OTHER');
CREATE TYPE "TaskPriority" AS ENUM ('LOW','MEDIUM','HIGH','URGENT');
CREATE TYPE "TaskStatus" AS ENUM ('TODO','IN_PROGRESS','IN_REVIEW','REVISION_REQUIRED','COMPLETED','CANCELLED');
CREATE TYPE "TaskAssignmentType" AS ENUM ('PRIMARY','COLLABORATOR');
CREATE TYPE "SubmissionStatus" AS ENUM ('PENDING_REVIEW','APPROVED','REVISION_REQUIRED');
CREATE TYPE "ReviewAction" AS ENUM ('APPROVE','REQUEST_REVISION');

CREATE TABLE "Task" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"teamId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"taskType" "TaskType" NOT NULL DEFAULT 'OTHER',"priority" "TaskPriority" NOT NULL DEFAULT 'MEDIUM',"status" "TaskStatus" NOT NULL DEFAULT 'TODO',"progressPercentage" INTEGER NOT NULL DEFAULT 0,"startDate" DATE,"dueDate" DATE,"estimatedHours" DECIMAL(8,2),"createdBy" TEXT NOT NULL,"updatedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"completedAt" TIMESTAMP(3),"archivedAt" TIMESTAMP(3),FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id"),FOREIGN KEY ("teamId") REFERENCES "Team"("id"),FOREIGN KEY ("createdBy") REFERENCES "User"("id"),FOREIGN KEY ("updatedBy") REFERENCES "User"("id"),CHECK ("progressPercentage" BETWEEN 0 AND 100),CHECK ("dueDate" IS NULL OR "startDate" IS NULL OR "dueDate">="startDate"),CHECK ("estimatedHours" IS NULL OR "estimatedHours">=0));
CREATE TABLE "TaskAssignee" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"userId" TEXT NOT NULL,"assignmentType" "TaskAssignmentType" NOT NULL DEFAULT 'PRIMARY',"assignedBy" TEXT NOT NULL,"assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("taskId") REFERENCES "Task"("id") ON DELETE CASCADE,FOREIGN KEY ("userId") REFERENCES "User"("id"),FOREIGN KEY ("assignedBy") REFERENCES "User"("id"));
CREATE TABLE "TaskSubtask" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"completed" BOOLEAN NOT NULL DEFAULT false,"position" INTEGER NOT NULL DEFAULT 0,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"completedAt" TIMESTAMP(3),FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("taskId") REFERENCES "Task"("id") ON DELETE CASCADE,FOREIGN KEY ("createdBy") REFERENCES "User"("id"));
CREATE TABLE "TaskComment" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"content" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deletedAt" TIMESTAMP(3),FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("taskId") REFERENCES "Task"("id") ON DELETE CASCADE,FOREIGN KEY ("authorId") REFERENCES "User"("id"));
CREATE TABLE "TaskActivity" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"actorUserId" TEXT,"activityType" TEXT NOT NULL,"description" TEXT NOT NULL,"previousValue" JSONB,"newValue" JSONB,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("taskId") REFERENCES "Task"("id") ON DELETE CASCADE,FOREIGN KEY ("actorUserId") REFERENCES "User"("id"));
CREATE TABLE "TaskSubmission" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"submittedBy" TEXT NOT NULL,"submissionNumber" INTEGER NOT NULL,"description" TEXT NOT NULL,"status" "SubmissionStatus" NOT NULL DEFAULT 'PENDING_REVIEW',"reviewComment" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"reviewedBy" TEXT,"reviewedAt" TIMESTAMP(3),FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("taskId") REFERENCES "Task"("id") ON DELETE CASCADE,FOREIGN KEY ("submittedBy") REFERENCES "User"("id"),FOREIGN KEY ("reviewedBy") REFERENCES "User"("id"));
CREATE TABLE "TaskDeliverable" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"submissionId" TEXT,"uploadedBy" TEXT NOT NULL,"fileName" TEXT NOT NULL,"fileSize" INTEGER NOT NULL,"mimeType" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("taskId") REFERENCES "Task"("id") ON DELETE CASCADE,FOREIGN KEY ("submissionId") REFERENCES "TaskSubmission"("id") ON DELETE CASCADE,FOREIGN KEY ("uploadedBy") REFERENCES "User"("id"));
CREATE TABLE "TaskReview" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"submissionId" TEXT NOT NULL,"reviewerId" TEXT NOT NULL,"action" "ReviewAction" NOT NULL,"comment" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("organizationId") REFERENCES "Organization"("id"),FOREIGN KEY ("taskId") REFERENCES "Task"("id") ON DELETE CASCADE,FOREIGN KEY ("submissionId") REFERENCES "TaskSubmission"("id") ON DELETE CASCADE,FOREIGN KEY ("reviewerId") REFERENCES "User"("id"));

CREATE UNIQUE INDEX "TaskAssignee_taskId_userId_key" ON "TaskAssignee"("taskId","userId");
CREATE UNIQUE INDEX "TaskSubmission_taskId_submissionNumber_key" ON "TaskSubmission"("taskId","submissionNumber");
CREATE INDEX "Task_organizationId_status_idx" ON "Task"("organizationId","status");
CREATE INDEX "Task_organizationId_dueDate_idx" ON "Task"("organizationId","dueDate");
CREATE INDEX "Task_organizationId_campaignId_idx" ON "Task"("organizationId","campaignId");
CREATE INDEX "Task_organizationId_teamId_idx" ON "Task"("organizationId","teamId");
CREATE INDEX "Task_organizationId_priority_idx" ON "Task"("organizationId","priority");
CREATE INDEX "Task_organizationId_createdAt_idx" ON "Task"("organizationId","createdAt");
CREATE INDEX "TaskAssignee_organizationId_userId_idx" ON "TaskAssignee"("organizationId","userId");
CREATE INDEX "TaskSubtask_organizationId_taskId_position_idx" ON "TaskSubtask"("organizationId","taskId","position");
CREATE INDEX "TaskComment_organizationId_taskId_createdAt_idx" ON "TaskComment"("organizationId","taskId","createdAt");
CREATE INDEX "TaskActivity_organizationId_taskId_createdAt_idx" ON "TaskActivity"("organizationId","taskId","createdAt");
CREATE INDEX "TaskSubmission_organizationId_taskId_status_idx" ON "TaskSubmission"("organizationId","taskId","status");
CREATE INDEX "TaskDeliverable_organizationId_taskId_idx" ON "TaskDeliverable"("organizationId","taskId");
CREATE INDEX "TaskReview_organizationId_taskId_createdAt_idx" ON "TaskReview"("organizationId","taskId","createdAt");
